        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Ateu! Não é verdade. Tenho passado a vida a criar deuses que morrem logo, idolos que depois derrubo. Uma estrela no ceu, algumas mulheres na terra..", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Resolvi estabelecer-me aqui na minha terra, município de Viçosa, Alagoas, e logo planeei adquirir a propriedade São Bernardo, onde trabalhei, no eito, com salário de cinco tostões.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Naquele segundo ano houve dificuldades medonhas. Plantei mamona e algodão, mas a safra foi ruim, os preços baixos, vivi meses aperreado, vendendo macacos e fazendo das fraquezas forças para não ir ao fundo.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Certos lugares que me davam prazer tornaram-se odiosos. Passo diante de uma livraria, olho com desgosto as vitrinas, tenho a impressão de que se acham ali pessoas, exibindo títulos e preços nos rostos, vendendo-se. É uma espécie de prostituição.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Os defeitos, porém, só me pareceram censuráveis no começo das nossas relações. Logo que se juntaram para formar com o resto uma criatura completa, achei-os naturais, e não poderia imaginar Marina sem eles, como não a poderia imaginar sem corpo.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Escolher marido por dinheiro. Que miséria! Não há pior espécie de prostituição.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "É uma tristeza. A senhora lavando, engomando, cozinhando, e seu Ramalho na quentura da usina elétrica, matando-se para sustentar os luxos daquela tonta. Sua filha não tem coração.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "A primeira coisa que guardei na memória foi um vaso de louça vidrada, cheio de pitombas, escondido atrás de uma porta.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Disseram-me depois que a escola nos servira de pouso numa viagem. Tinhamos deixado a cidadezinha onde vivíamos, em Alagoas, entrávamos no sertão de Pernambuco, eu, meu pai, minha mãe, duas irmãs.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Quem dormiu no chão deve lembra-se disto, impor-se disciplina, sentar-se em cadeiras duras, escrever em tábuas estreitas. Escreverá talvez asperezas, mas é delas que a vida é feita: inútil negá-las, controná-las, envovê-las em gaze.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Se a única coisa que de o homem terá certeza é a morte; a única certeza do brasileiro é o carnaval no próximo ano.", Author = "Graciliano Ramos" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Graciliano_Ramos", Text = "Se a igualdade entre os homens- que busco e desejo- for o desrespeito ao ser humano, fugirei dela.", Author = "Graciliano Ramos" },
        };
